497: export function buildAtlas() {
498:   if (atlasCanvas) return atlasCanvas
499:   const canvas = document.createElement('canvas')
500:   canvas.width = ATLAS_SIZE
501:   canvas.height = ATLAS_SIZE
502:   const ctx = canvas.getContext('2d')
503:   ctx.imageSmoothingEnabled = false
504:   const at = (tile) => [(tile % ATLAS_COLS) * TILE, Math.floor(tile / ATLAS_COLS) * TILE]
505:   const rnd = mulberry32(0x5eed1234)
506:   const draw = (tile, fn) => fn(ctx, ...at(tile), rnd)
507: 
508:   draw(T.grassTop, paintGrassTop)
509:   draw(T.grassSide, paintGrassSide)
510:   draw(T.dirt, paintDirt)
511:   draw(T.stone, paintStone)
512:   draw(T.cobble, paintCobble)
513:   draw(T.sand, paintSand)
514:   draw(T.oakSide, paintOakSide)
515:   draw(T.oakTop, paintOakTop)
516:   draw(T.oakLeaves, (c, x, y, r) => paintLeaves(c, x, y, r, false))
517:   draw(T.planks, paintPlanks)
518:   draw(T.glass, paintGlass)
519:   draw(T.water, paintWater)
520:   draw(T.bedrock, paintBedrock)
521:   draw(T.snow, paintSnow)
522:   draw(T.snowSide, paintSnowSide)
523:   draw(T.gravel, paintGravel)
524:   draw(T.sandstoneSide, paintSandstoneSide)
525:   draw(T.sandstoneTop, paintSandstoneTop)
526:   draw(T.coalOre, (c, x, y, r) => paintOre(c, x, y, r, '#222222', '#4a4a4a'))
527:   draw(T.ironOre, (c, x, y, r) => paintOre(c, x, y, r, '#b28b6a', '#d8b58f'))
528:   draw(T.bricks, paintBricks)
529:   draw(T.birchSide, paintBirchSide)
530:   draw(T.birchTop, paintBirchTop)
531:   draw(T.birchLeaves, (c, x, y, r) => paintLeaves(c, x, y, r, true))
532:   draw(T.obsidian, paintObsidian)
533:   draw(T.glowstone, paintGlowstone)
534:   draw(T.craftingTop, paintCraftingTop)
535:   draw(T.craftingSide, paintCraftingSide)
536:   draw(T.flowerRed, (c, x, y, r) => paintFlower(c, x, y, r, '#d83b31', '#f6d552'))
537:   draw(T.flowerYellow, (c, x, y, r) => paintFlower(c, x, y, r, '#f2d33c', '#c98a24'))
538:   draw(T.grassTuft, paintGrassTuft)
539:   draw(T.deadBush, paintDeadBush)
540:   draw(T.pumpkinSide, paintPumpkinSide)
541:   draw(T.pumpkinTop, paintPumpkinTop)
542:   draw(T.whiteWool, (c, x, y, r) => paintWool(c, x, y, r, '#e9e9e9', '#cfcfcf', '#ffffff'))
543:   draw(T.redWool, (c, x, y, r) => paintWool(c, x, y, r, '#b02e26', '#8e211b', '#d2463c'))
544:   draw(T.blueWool, (c, x, y, r) => paintWool(c, x, y, r, '#3c44aa', '#2b3185', '#5860d1'))
545:   draw(T.yellowWool, (c, x, y, r) => paintWool(c, x, y, r, '#fed83d', '#d9b62a', '#fff08a'))
546:   draw(T.stoneBricks, paintStoneBricks)
547:   draw(T.mossyStone, paintMossyStone)
548: 
549:   atlasCanvas = canvas
550:   return canvas
551: }
