569: export function createWaterNormalTexture() {
570:   const size = 64
571:   const canvas = document.createElement('canvas')
572:   canvas.width = size
573:   canvas.height = size
574:   const ctx = canvas.getContext('2d')
575:   const image = ctx.createImageData(size, size)
576:   const rnd = mulberry32(987)
577:   const waves = [
578:     { fx: 0.2, fy: 0.11, amp: 1.0, phase: rnd() * 6.28 },
579:     { fx: 0.09, fy: 0.23, amp: 0.7, phase: rnd() * 6.28 },
580:     { fx: 0.31, fy: -0.17, amp: 0.5, phase: rnd() * 6.28 },
581:   ]
582:   const height = (x, y) => {
583:     let h = 0
584:     for (const w of waves) h += Math.sin((x * w.fx + y * w.fy) * Math.PI * 2 + w.phase) * w.amp
585:     return h
586:   }
587:   for (let y = 0; y < size; y++) {
588:     for (let x = 0; x < size; x++) {
589:       const hx = height(x + 1, y) - height(x - 1, y)
590:       const hy = height(x, y + 1) - height(x, y - 1)
591:       const nx = -hx * 0.35
592:       const ny = -hy * 0.35
593:       const nz = 1
594:       const len = Math.hypot(nx, ny, nz)
595:       const i = (y * size + x) * 4
596:       image.data[i] = ((nx / len) * 0.5 + 0.5) * 255
597:       image.data[i + 1] = ((ny / len) * 0.5 + 0.5) * 255
598:       image.data[i + 2] = ((nz / len) * 0.5 + 0.5) * 255
599:       image.data[i + 3] = 255
600:     }
601:   }
602:   ctx.putImageData(image, 0, 0)
603:   const texture = new THREE.CanvasTexture(canvas)
604:   texture.wrapS = THREE.RepeatWrapping
605:   texture.wrapT = THREE.RepeatWrapping
606:   texture.magFilter = THREE.LinearFilter
607:   texture.minFilter = THREE.LinearMipmapLinearFilter
608:   texture.colorSpace = THREE.NoColorSpace
609:   return texture
610: }
