651: export function tileUV(tile, inset = 0.001) {
652:   const col = tile % ATLAS_COLS
653:   const row = Math.floor(tile / ATLAS_COLS)
654:   const u0 = col / ATLAS_COLS + inset
655:   const u1 = (col + 1) / ATLAS_COLS - inset
656:   const v1 = 1 - row / ATLAS_COLS - inset
657:   const v0 = 1 - (row + 1) / ATLAS_COLS + inset
658:   return { u0, u1, v0, v1 }
659: }
