661: const tileCanvasCache = new Map()
662: 
663: function getTileCanvas(tile) {
664:   if (tileCanvasCache.has(tile)) return tileCanvasCache.get(tile)
665:   const atlas = buildAtlas()
666:   const canvas = document.createElement('canvas')
667:   canvas.width = TILE
668:   canvas.height = TILE
669:   const ctx = canvas.getContext('2d')
670:   ctx.imageSmoothingEnabled = false
671:   const col = tile % ATLAS_COLS
672:   const row = Math.floor(tile / ATLAS_COLS)
673:   ctx.drawImage(atlas, col * TILE, row * TILE, TILE, TILE, 0, 0, TILE, TILE)
674:   tileCanvasCache.set(tile, canvas)
675:   return canvas
676: }
