678: export function createBlockIcon(blockId, size = 96) {
679:   const block = BLOCKS[blockId]
680:   if (!block) return null
681:   const canvas = document.createElement('canvas')
682:   canvas.width = size
683:   canvas.height = size
684:   const ctx = canvas.getContext('2d')
685:   ctx.imageSmoothingEnabled = false
686:   const s = size / 64
687:   const ox = size / 2
688:   const oy = size / 2 - 2 * s
689: 
690:   if (block.cross) {
691:     ctx.save()
692:     ctx.setTransform(size / 32, 0, 0, size / 32, 0, 0)
693:     ctx.drawImage(getTileCanvas(block.tiles[0]), 0, 0, 16, 16, 0, 0, 32, 32)
694:     ctx.restore()
695:     return canvas
696:   }
697: 
698:   // top face
699:   ctx.save()
700:   ctx.setTransform(2 * s, -1 * s, 2 * s, 1 * s, ox - 32 * s, oy - 16 * s)
701:   ctx.drawImage(getTileCanvas(block.tiles[0]), 0, 0, 16, 16, 0, 0, 16, 16)
702:   ctx.restore()
703: 
704:   // left face
705:   ctx.save()
706:   ctx.setTransform(2 * s, 1 * s, 0, 2 * s, ox - 32 * s, oy + 16 * s)
707:   ctx.drawImage(getTileCanvas(block.tiles[2]), 0, 0, 16, 16, 0, 0, 16, 16)
708:   ctx.fillStyle = 'rgba(0,0,0,0.24)'
709:   ctx.fillRect(0, 0, 16, 16)
710:   ctx.restore()
711: 
712:   // right face
713:   ctx.save()
714:   ctx.setTransform(2 * s, -1 * s, 0, 2 * s, ox, oy + 32 * s)
715:   ctx.drawImage(getTileCanvas(block.tiles[2]), 0, 0, 16, 16, 0, 0, 16, 16)
716:   ctx.fillStyle = 'rgba(0,0,0,0.4)'
717:   ctx.fillRect(0, 0, 16, 16)
718:   ctx.restore()
719:   return canvas
720: }
