722: export function blockAverageColor(blockId) {
723:   if (blockId === 10) return '#3f93c9'
724:   const block = BLOCKS[blockId]
725:   if (!block) return '#888888'
726:   const src = getTileCanvas(block.tiles[2])
727:   const ctx = src.getContext('2d')
728:   const data = ctx.getImageData(0, 0, TILE, TILE).data
729:   let r = 0
730:   let g = 0
731:   let b = 0
