const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('console', (m) => console.log('console', m.type(), m.text()))
page.on('pageerror', (e) => console.log('pageerror', e.message))
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.waitForFunction(() => document.fonts.status === 'loaded')
const control = page.locator('#playBtn')
console.log('visible', await control.isVisible(), 'enabled', await control.isEnabled())
console.log('element at center', await page.evaluate(() => {
  const b = document.getElementById('playBtn').getBoundingClientRect()
  const el = document.elementFromPoint(b.x + b.width / 2, b.y + b.height / 2)
  return { tag: el?.tagName, id: el?.id, cls: el?.className, pointer: getComputedStyle(el).pointerEvents }
}))
for (let i = 0; i < 6; i++) {
  try {
    await control.click({ trial: true, timeout: 1500 })
    console.log('trial click ok at attempt', i)
    break
  } catch (error) {
    console.log('attempt', i, error.name, error.message.split('\n')[0])
    await page.waitForTimeout(300)
  }
}
await browser.close()

import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 })
await page.waitForFunction(() => document.fonts.status === 'loaded')
for (let round = 0; round < 5; round++) {
  const matches = []
  for (const control of await page.locator('button, input[type="button"], input[type="submit"], [role="button"]').all()) {
    if (!(await control.isVisible()) || !(await control.isEnabled())) continue
    const eligible = await control.evaluate((element) => {
      if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false
      const label = element.getAttribute('aria-label') || element.value || element.textContent || ''
      return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
    })
    if (eligible) matches.push(await control.evaluate((el) => el.id + '|' + el.className))
  }
  console.log('round', round, JSON.stringify(matches))
  await page.waitForTimeout(250)
}
await browser.close()

